// Unit test for removeItem updating subtotal correctly.
// Regression test for bug where removing an item did not update cart totals.
import { test } from "node:test";
import assert from "node:assert/strict";

import {
  addItem, createCart, removeItem, totals,
} from "../public/cart.js";

test("removing an item updates the subtotal", () => {
  const cart = createCart();
  // Add three items: cap ($24.00), stickers ($4.99), mug ($12.50)
  addItem(cart, "cap");      // 2400 cents
  addItem(cart, "stickers"); // 499 cents
  addItem(cart, "mug");      // 1250 cents
  // Initial subtotal should be 2400+499+1250 = 4149 cents
  assert.equal(totals(cart).subtotal, 4149);

  // Remove the cap
  removeItem(cart, "cap");
  // New subtotal should be 499+1250 = 1749 cents
  assert.equal(totals(cart).subtotal, 1749);
});

test("removing an item with quantity > 1 updates subtotal correctly", () => {
  const cart = createCart();
  // Add two caps (quantity 2)
  addItem(cart, "cap", 2); // 2 * 2400 = 4800 cents
  addItem(cart, "stickers"); // 499 cents
  assert.equal(totals(cart).subtotal, 5299);

  // Remove caps entirely
  removeItem(cart, "cap");
  assert.equal(totals(cart).subtotal, 499);
});

